insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Acetaminofén', 'Analgésico', 'cat-analg', '500 mg', 'Alivia el dolor leve a moderado y reduce la fiebre. Es uno de los analgésicos más seguros y usados a nivel mundial.', '500–1000 mg cada 6–8 horas. Máximo 4 g/día en adultos.', 'Dolor de cabeza, fiebre, dolor muscular, molestias generales.', 'Es mi primer consejo cuando hay fiebre o dolor leve. Muy seguro si se toma bien. ¡Ojo con la dosis!', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ibuprofeno', 'Analgésico', 'cat-analg', '400 mg', 'Antiinflamatorio no esteroideo (AINE). Alivia el dolor, reduce la inflamación y baja la fiebre.', '400–600 mg cada 6–8 horas. Tomar con alimentos.', 'Dolor muscular, articular, menstrual, dolor de cabeza, fiebre, golpes.', 'Ideal para golpes e inflamación. Siempre acompáñalo con una comida, así no irrita el estómago.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Aspirina', 'Analgésico', 'cat-analg', '500 mg', 'Analgésico, antipirético y antiagregante plaquetario.', '500 mg cada 8 horas para dolor.', 'Dolor, fiebre, prevención cardiovascular (solo con prescripción).', 'La aspirina es antigua pero efectiva. En niños: nunca. Para el corazón: solo con tu médico.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Loratadina', 'Antihistamínico', 'cat-antih', '10 mg', 'Antihistamínico de segunda generación. Alivia síntomas de alergias sin causar mucho sueño.', '10 mg una vez al día.', 'Rinitis alérgica, urticaria, alergia al polvo o pólenes, picaduras.', 'Mi favorita para las alergias. No da tanto sueño y funciona todo el día con una sola dosis.', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Cetirizina', 'Antihistamínico', 'cat-antih', '10 mg', 'Antihistamínico que alivia síntomas de alergia estacional y urticaria crónica.', '10 mg una vez al día, preferiblemente en la noche.', 'Alergias, urticaria, eccema alérgico, ojos llorosos por alergia.', 'Si tienes alergia y además te cuesta dormir, la cetirizina tomada de noche te ayuda con ambos.', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Amoxicilina', 'Antibiótico', 'cat-antib', '500 mg', 'Antibiótico de amplio espectro. Trata infecciones bacterianas como amigdalitis, otitis, bronquitis.', '500 mg cada 8 horas por 7–10 días.', 'Solo con indicación médica. Infecciones confirmadas por bacteria.', 'Los antibióticos son serios. Solo úsame si el médico lo indica. ¡Y completa el tratamiento!', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Azitromicina', 'Antibiótico', 'cat-antib', '500 mg', 'Antibiótico macrólido. Trata infecciones respiratorias y de piel.', '500 mg una vez al día por 3–5 días.', 'Solo con prescripción. Neumonía leve, sinusitis, infecciones de piel.', 'Azitromicina se toma pocos días pero actúa varios días más en el cuerpo. No la uses sin tu médico.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Omeprazol', 'Gastroprotector', 'cat-gast', '20 mg', 'Reduce la producción de ácido en el estómago. Trata gastritis, úlcera y reflujo.', '20 mg una vez al día, en ayunas, 30 minutos antes del desayuno.', 'Acidez, gastritis, reflujo, úlcera.', 'Cuando el estómago arde, omeprazol al rescate. Mejor tomarlo antes del desayuno.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ranitidina', 'Gastroprotector', 'cat-gast', '150 mg', 'Reduce la producción de ácido gástrico. Trata úlceras, reflujo y gastritis.', '150 mg dos veces al día.', 'Acidez puntual, gastritis, reflujo leve.', 'La ranitidina es una buena opción para la acidez rápida. Si el problema es frecuente, visita al médico.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Vitamina C', 'Vitamina', 'cat-vita', '500 mg', 'Antioxidante esencial. Refuerza el sistema inmune y mejora la absorción de hierro.', '500–1000 mg al día.', 'Prevención de resfriados, refuerzo inmune, suplemento diario.', '¡La vitamina C es mi aliada! Especialmente en temporada de gripes.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Vitamina D3', 'Vitamina', 'cat-vita', '1000 UI', 'Esencial para absorción de calcio, salud ósea y función inmunológica.', '1000–2000 UI al día con una comida con grasas.', 'Suplemento diario, especialmente con poca exposición solar.', 'El sol es la mejor fuente de vitamina D, pero si no te da mucho el sol, un suplemento ayuda.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metformina', 'Antidiabético', 'cat-card', '500 mg', 'Medicamento de primera línea para diabetes tipo 2.', '500–1000 mg con las comidas.', 'Únicamente bajo prescripción médica para diabetes tipo 2.', 'La metformina es un medicamento serio para la diabetes. Solo con receta médica y seguimiento regular.', '🩺');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Enalapril', 'Cardiovascular', 'cat-card', '10 mg', 'Trata la hipertensión arterial y la insuficiencia cardíaca.', '5–20 mg una vez al día.', 'Solo bajo prescripción médica para hipertensión.', 'La presión alta es silenciosa pero peligrosa. Si te lo recetaron, tómalo todos los días.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Salbutamol', 'Respiratorio', 'cat-resp', '100 mcg', 'Broncodilatador de acción rápida. Alivia el broncoespasmo en asma.', '1–2 inhalaciones cuando sea necesario.', 'Crisis asmática, dificultad respiratoria.', 'Si tienes asma, el salbutamol es tu salvavidas en una crisis. ¡Siempre tenlo a mano!', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ambroxol', 'Respiratorio', 'cat-resp', '30 mg', 'Mucolítico. Adelgaza el moco y facilita su expulsión.', '30 mg tres veces al día con abundante agua.', 'Bronquitis, tos con flema, catarro.', 'Cuando hay mucho moco y la tos no cede, el ambroxol ayuda a expulsarlo. ¡Agua, agua y más agua!', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Diclofenaco', 'Analgésico', 'cat-analg', '50 mg', 'Antiinflamatorio potente. Trata dolor agudo con componente inflamatorio.', '50 mg dos o tres veces al día con alimentos.', 'Dolor articular, lumbalgia, golpes con inflamación.', 'Diclofenaco es poderoso para la inflamación. Siempre con comida y no más tiempo del necesario.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Tramadol', 'Analgésico', 'cat-analg', '50 mg', 'Analgésico opioide para dolor moderado a intenso.', '50–100 mg cada 4–6 horas. Solo bajo prescripción.', 'SOLO CON PRESCRIPCIÓN MÉDICA.', 'El tramadol es para dolores fuertes y solo con receta. Nunca te automediques con este.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metoclopramida', 'Gastroprotector', 'cat-gast', '10 mg', 'Antiemético. Alivia las náuseas y vómitos.', '10 mg tres veces al día, 30 minutos antes de las comidas.', 'Náuseas, vómitos, sensación de llenura.', 'Cuando el estómago no quiere cooperar y hay náuseas, la metoclopramida ayuda a calmarlo.', '🟡');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Hidrocortisona crema', 'Dermatológico', 'cat-derm', '1%', 'Corticoide tópico. Reduce inflamación y picor en condiciones alérgicas de piel.', 'Aplicar capa fina en zona afectada 1–3 veces al día.', 'Eccema leve, dermatitis, picazón por alergia.', 'Para el picor y la irritación de piel, la hidrocortisona crema funciona bien. Poquito y pocos días.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Clotrimazol crema', 'Dermatológico', 'cat-derm', '1%', 'Antifúngico tópico. Trata infecciones por hongos.', 'Aplicar capa fina 2–3 veces al día por 2–4 semanas.', 'Hongos en piel, pie de atleta, candidiasis.', 'Los hongos en la piel se tratan. La clave es completar el tratamiento y mantener la zona seca.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Solución salina', 'Respiratorio', 'cat-resp', '0.9%', 'Higiene nasal. Limpia y humedece las mucosas nasales.', '2–3 gotas en cada fosa nasal, 3–4 veces al día.', 'Congestión nasal, catarro, rinitis.', 'La solución salina es de mis mejores amigas. Sin efectos secundarios, segura para todos. ¡Siempre tenla!', '🫧');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Suero oral (SRO)', 'Gastroprotector', 'cat-gast', 'Sachet', 'Sales de rehidratación oral. Repone líquidos y electrolitos perdidos.', 'Disolver un sobre en 1 litro de agua. Beber a sorbos frecuentes.', 'Diarrea, vómitos, deshidratación.', 'Cuando hay diarrea o vómito, lo primero es no deshidratarse. El suero oral es simple y muy efectivo.', '💧');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Loperamida', 'Gastroprotector', 'cat-gast', '2 mg', 'Antidiarreico. Reduce la frecuencia de deposiciones en diarrea aguda.', '2 mg tras cada deposición blanda. Máximo 8 mg/día.', 'Diarrea aguda no infecciosa.', 'La loperamida detiene la diarrea rápido. Si hay fiebre o sangre, eso necesita médico.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Melatonina', 'Vitamina', 'cat-vita', '3 mg', 'Regula el ciclo de sueño. Ayuda a conciliar el sueño.', '0.5–3 mg, 30 minutos antes de dormir.', 'Insomnio leve, jet lag, desfase del ciclo de sueño.', 'Si tienes dificultad para dormir, la melatonina puede ayudar a resetear tu reloj interno.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Losartán', 'Cardiovascular', 'cat-card', '50 mg', 'Trata la hipertensión arterial.', '25–100 mg una vez al día.', 'Solo bajo prescripción médica.', 'El losartán mantiene la presión bajo control. La hipertensión no duele pero daña silenciosamente.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Clorfeniramina', 'Antihistamínico', 'cat-antih', '4 mg', 'Antihistamínico de primera generación. Alivia síntomas de alergia y resfriado.', '4 mg cada 4–6 horas.', 'Rinitis alérgica, urticaria, picazón.', 'La clorfeniramina funciona muy bien para la alergia, pero da bastante sueño. Perfecta para tomar de noche.', '🩹');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Naproxeno', 'Analgésico', 'cat-analg', '550 mg', 'Antiinflamatorio de larga duración.', '250–550 mg dos veces al día con comida.', 'Dolor menstrual, artritis, dolor muscular.', 'El naproxeno dura más que el ibuprofeno. Genial para el dolor menstrual, pero siempre con comida.', '🌡️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Pantoprazol', 'Gastroprotector', 'cat-gast', '40 mg', 'Inhibidor de la bomba de protones. Trata reflujo severo y úlceras.', '40 mg una vez al día en ayunas.', 'Reflujo severo, úlcera péptica.', 'El pantoprazol es más potente para el reflujo severo. Si el omeprazol no alcanzó, este puede ser la respuesta.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Atorvastatina', 'Cardiovascular', 'cat-card', '20 mg', 'Reduce colesterol LDL y triglicéridos. Previene eventos cardiovasculares.', '10–80 mg una vez al día, en la noche.', 'Solo bajo prescripción para hipercolesterolemia.', 'El colesterol alto no se siente pero obstruye las arterias. La atorvastatina trabaja mejor mientras duermes.', '🩺');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Zinc', 'Vitamina', 'cat-vita', '20 mg', 'Mineral esencial para el sistema inmune y cicatrización.', '20–50 mg al día con alimentos.', 'Suplemento inmune, durante resfriados.', 'El zinc ayuda al sistema inmune y acelera la recuperación del resfriado. Un gran aliado en temporadas de gripe.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ketorolaco', 'Analgésico', 'cat-analg', '10 mg', 'Antiinflamatorio no esteroideo de potencia alta. Para dolor agudo e intenso.', '10 mg cada 4–6 horas. Máximo 5 días de uso.', 'Dolor postoperatorio, cólico renal, dolor dental intenso.', 'El ketorolaco es uno de los AINEs más potentes. Eficaz para dolores fuertes, pero solo por pocos días.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Cafeína + Acetaminofén', 'Analgésico', 'cat-analg', '65/500 mg', 'Combinación que potencia el efecto analgésico. Usada para cefalea y migraña.', '1 tableta cada 6 horas según necesidad.', 'Dolor de cabeza, migraña leve, cefalea tensional.', 'La cafeína potencia el acetaminofén y lo hace más efectivo para el dolor de cabeza. ¡Pero cuidado si eres sensible al café!', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Meloxicam', 'Analgésico', 'cat-analg', '15 mg', 'AINE selectivo con menor irritación gástrica. Para dolor inflamatorio crónico.', '7.5–15 mg una vez al día con comida.', 'Artritis, artrosis, dolor articular crónico.', 'El meloxicam es más amigable con el estómago que otros AINEs. Buena opción para dolores articulares crónicos.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metamizol', 'Analgésico', 'cat-analg', '500 mg', 'Analgésico y antipirético potente. Eficaz para dolores cólicos y fiebre alta.', '500–1000 mg cada 6–8 horas.', 'Cólicos, fiebre alta resistente, dolor visceral.', 'El metamizol va muy bien para los cólicos. Actúa rápido y baja la fiebre con eficacia.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ciprofloxacino', 'Antibiótico', 'cat-antib', '500 mg', 'Antibiótico fluoroquinolona. Amplio espectro para infecciones urinarias y gastrointestinales.', '500 mg cada 12 horas por 7–10 días.', 'Solo con prescripción. Infecciones urinarias, gastrointestinales.', 'El ciprofloxacino es muy efectivo para infecciones urinarias, pero es un antibiótico serio. Solo con receta.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metronidazol', 'Antibiótico', 'cat-antib', '500 mg', 'Antibiótico y antiparasitario. Trata infecciones por anaerobios y parásitos.', '500 mg cada 8 horas por 7 días.', 'Solo con prescripción. Amebiasis, giardiasis, vaginosis bacteriana.', 'El metronidazol es el campeón contra ciertos parásitos. Recuerda: ni una gota de alcohol mientras lo tomes.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Claritromicina', 'Antibiótico', 'cat-antib', '500 mg', 'Antibiótico macrólido. Trata infecciones respiratorias y Helicobacter pylori.', '250–500 mg cada 12 horas por 7–14 días.', 'Solo con prescripción. Neumonía, sinusitis, H. pylori.', 'La claritromicina es aliada contra la bacteria del estómago y las infecciones respiratorias. Solo con indicación médica.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Trimetoprim/Sulfametoxazol', 'Antibiótico', 'cat-antib', '800/160 mg', 'Antibiótico combinado para infecciones urinarias y respiratorias.', '800/160 mg cada 12 horas por 7–14 días.', 'Solo con prescripción. ITU, bronquitis bacteriana.', 'Una combinación clásica para las infecciones de orina. Hidratación abundante para proteger los riñones.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Doxiciclina', 'Antibiótico', 'cat-antib', '100 mg', 'Antibiótico tetraciclina. Trata infecciones respiratorias, de piel y enfermedades de transmisión vectorial.', '100 mg cada 12 horas por 7–14 días.', 'Solo con prescripción. Neumonía atípica, acné, dengue.', 'La doxiciclina cubre muchas infecciones. Si la tomas, protégete del sol porque puede irritar la piel.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Amoxicilina/Clavulanato', 'Antibiótico', 'cat-antib', '875/125 mg', 'Antibiótico de amplio espectro resistente a betalactamasas.', '875/125 mg cada 12 horas con alimentos.', 'Solo con prescripción. Sinusitis, otitis, infecciones de piel.', 'El augmentín es más potente que la amoxicilina sola. Muy usado cuando hay resistencia bacteriana.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Desloratadina', 'Antihistamínico', 'cat-antih', '5 mg', 'Antihistamínico de tercera generación. Sin somnolencia. Dura 24 horas.', '5 mg una vez al día.', 'Rinitis alérgica, urticaria crónica, alergias.', 'La desloratadina es la más moderna de las antihistaminas. Sin sueño, sin molestias, y solo una al día.', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Fexofenadina', 'Antihistamínico', 'cat-antih', '120 mg', 'Antihistamínico sin sedación. Muy bien tolerado.', '120 mg una vez al día o 60 mg dos veces al día.', 'Rinitis alérgica, urticaria, alergia estacional.', 'La fexofenadina es muy segura y no da sueño. Ideal para quienes manejan o trabajan con maquinaria.', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Difenhidramina', 'Antihistamínico', 'cat-antih', '25 mg', 'Antihistamínico de primera generación. También usado como inductor del sueño.', '25–50 mg al momento de acostarse para el sueño.', 'Alergia, insomnio ocasional, mareo por viaje.', 'La difenhidramina da bastante sueño, lo cual a veces es justo lo que se necesita. ¡Pero solo ocasionalmente!', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Esomeprazol', 'Gastroprotector', 'cat-gast', '40 mg', 'Inhibidor de bomba de protones de nueva generación. Potente control del ácido.', '40 mg una vez al día en ayunas.', 'Reflujo gastroesofágico, úlcera, gastritis erosiva.', 'El esomeprazol es uno de los más efectivos para el reflujo severo. Tomaolo 30 min antes del desayuno.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Sucralfato', 'Gastroprotector', 'cat-gast', '1 g', 'Protector de la mucosa gástrica. Crea una barrera sobre la úlcera.', '1 g cuatro veces al día, en ayunas y al acostarse.', 'Úlcera péptica, gastritis, protección gástrica.', 'El sucralfato actúa como un parche sobre la úlcera. Tómalo bien separado de otras pastillas.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Domperidona', 'Gastroprotector', 'cat-gast', '10 mg', 'Procinético. Acelera el vaciamiento gástrico y reduce náuseas.', '10 mg tres veces al día, 15 minutos antes de las comidas.', 'Náuseas, distensión, digestión lenta, reflujo.', 'La domperidona ayuda al estómago a funcionar más rápido. Excelente cuando la comida parece que no pasa.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Bicarbonato de sodio', 'Gastroprotector', 'cat-gast', 'Polvo', 'Antiácido de acción rápida. Neutraliza el ácido del estómago temporalmente.', 'Media cucharadita en un vaso de agua fría.', 'Acidez puntual, ardor de estómago.', 'El bicarbonato es el remedio más casero para la acidez. Funciona rápido, pero no es para todos los días.', '🟡');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Dimeticona', 'Gastroprotector', 'cat-gast', '80 mg', 'Antiflatulentor. Elimina el gas acumulado en el tracto digestivo.', '80 mg tres veces al día después de las comidas.', 'Gases, distensión abdominal, meteorismo.', 'Cuando el gas no da tregua, la dimeticona al rescate. Segura y sin efectos secundarios importantes.', '🟡');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Amlodipino', 'Cardiovascular', 'cat-card', '5 mg', 'Bloqueador de canales de calcio. Trata la hipertensión y angina de pecho.', '5–10 mg una vez al día.', 'Solo bajo prescripción para hipertensión y angina.', 'El amlodipino relaja los vasos sanguíneos y baja la presión. Es de los más usados para la hipertensión.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Furosemida', 'Cardiovascular', 'cat-card', '40 mg', 'Diurético de asa. Elimina el exceso de líquido en insuficiencia cardíaca e hipertensión.', '20–80 mg al día en la mañana.', 'Solo con prescripción médica. Edema, insuficiencia cardíaca.', 'La furosemida hace que el cuerpo elimine líquidos. Siempre por la mañana para que no interrumpa el sueño.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Espironolactona', 'Cardiovascular', 'cat-card', '25 mg', 'Diurético ahorrador de potasio. Útil en insuficiencia cardíaca e hipertensión.', '25–100 mg al día.', 'Solo con prescripción. Insuficiencia cardíaca, hipertensión, edema.', 'La espironolactona es un diurético que no baja el potasio. Se usa mucho en enfermedades del corazón.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metoprolol', 'Cardiovascular', 'cat-card', '50 mg', 'Betabloqueador. Controla la frecuencia cardíaca y trata hipertensión y angina.', '50–100 mg dos veces al día.', 'Solo con prescripción. Hipertensión, arritmias, angina.', 'El metoprolol enlentece y regula el corazón. Nunca lo pares de golpe — siempre consulta a tu médico.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Glibenclamida', 'Antidiabético', 'cat-card', '5 mg', 'Sulfonilurea. Estimula la producción de insulina en diabetes tipo 2.', '2.5–15 mg al día con el desayuno.', 'Solo con prescripción para diabetes tipo 2.', 'La glibenclamida estimula al páncreas a producir más insulina. Siempre con comida para evitar bajones de azúcar.', '🩺');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Insulina NPH', 'Antidiabético', 'cat-card', '100 UI/ml', 'Insulina de acción intermedia para control de glucemia en diabetes.', 'Según indicación médica estricta — variable.', 'Únicamente bajo prescripción y supervisión médica.', 'La insulina es esencial para muchos diabéticos. Su dosis es muy personal y debe ser manejada con tu médico.', '🩺');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Budesonida inhalada', 'Respiratorio', 'cat-resp', '200 mcg', 'Corticoide inhalado. Controla la inflamación crónica en asma y EPOC.', '200–400 mcg dos veces al día (mantenimiento).', 'Asma crónica, EPOC — bajo prescripción médica.', 'La budesonida es para el control diario del asma, no para la crisis. ¡Y siempre enjuaga la boca después!', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Montelukast', 'Respiratorio', 'cat-resp', '10 mg', 'Antagonista de leucotrienos. Previene síntomas de asma y rinitis alérgica.', '10 mg una vez al día en la noche.', 'Solo con prescripción. Asma leve-moderada, rinitis alérgica.', 'El montelukast ayuda a prevenir las crisis de asma. Se toma de noche y actúa durante el día siguiente.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Dextrometorfano', 'Respiratorio', 'cat-resp', '15 mg', 'Antitusivo. Suprime la tos seca e irritativa.', '15–30 mg cada 4–6 horas según necesidad.', 'Tos seca, tos irritativa, tos nocturna.', 'Dextrometorfano frena la tos seca. Pero si hay flema, necesitas un mucolítico — no este.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Bromuro de ipratropio', 'Respiratorio', 'cat-resp', '20 mcg', 'Broncodilatador anticolinérgico. Trata broncoespasmo en EPOC y asma.', '2 inhalaciones 3–4 veces al día.', 'Solo con prescripción. EPOC, bronquitis crónica, asma.', 'El ipratropio abre los bronquios de una forma diferente al salbutamol. Muy útil en EPOC.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Prednisona', 'Respiratorio', 'cat-resp', '20 mg', 'Corticoide oral sistémico. Reduce la inflamación en crisis asmáticas y alergias graves.', '20–60 mg al día según indicación médica, con alimentos.', 'Solo con prescripción. Crisis asmática, alergias graves, inflamación.', 'La prednisona es potente antiinflamatoria. Muy eficaz pero debe usarse el tiempo justo y suspenderse gradualmente.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Complejo B', 'Vitamina', 'cat-vita', 'Comprimido', 'Suplemento de vitaminas del grupo B. Apoya el sistema nervioso y la energía celular.', '1 comprimido al día con el desayuno.', 'Fatiga, suplemento en embarazo, deficiencias nutricionales.', 'El complejo B es el suplemento de la energía. Si te sientes fatigado sin causa clara, puede ayudarte.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ácido fólico', 'Vitamina', 'cat-vita', '400 mcg', 'Vitamina B9. Esencial en el embarazo para prevenir defectos del tubo neural.', '400–800 mcg al día.', 'Embarazo o planeación del mismo, anemia megaloblástica.', 'El ácido fólico es vital antes y durante el embarazo. Toda mujer en edad fértil debería tomarlo.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Hierro (Sulfato ferroso)', 'Vitamina', 'cat-vita', '325 mg', 'Suplemento de hierro. Trata y previene la anemia ferropénica.', '325 mg una o dos veces al día en ayunas.', 'Anemia por déficit de hierro, embarazo, menstruaciones abundantes.', 'El hierro combate la anemia. Tómalo con jugo de naranja — la vitamina C ayuda a absorberlo mucho mejor.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Calcio + Vitamina D', 'Vitamina', 'cat-vita', '600/400 mg/UI', 'Suplemento para la salud ósea. Previene osteoporosis.', '600–1200 mg de calcio con vitamina D al día.', 'Prevención de osteoporosis, mujeres posmenopáusicas, adultos mayores.', 'El calcio con vitamina D es el dúo perfecto para los huesos fuertes. Especialmente importante después de los 50.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Magnesio', 'Vitamina', 'cat-vita', '400 mg', 'Mineral esencial para músculos, nervios y regulación de glucosa.', '400 mg al día en la noche.', 'Calambres musculares, insomnio, suplemento general.', 'El magnesio relaja los músculos y ayuda a dormir. Si tienes calambres nocturnos, este puede ser tu aliado.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Omega-3', 'Vitamina', 'cat-vita', '1000 mg', 'Ácidos grasos esenciales. Protegen el corazón y reducen la inflamación.', '1000 mg una o dos veces al día con las comidas.', 'Suplemento cardiovascular, colesterol elevado, inflamación.', 'El omega-3 cuida el corazón y los vasos sanguíneos. El pescado azul es la fuente natural, pero el suplemento también funciona.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Aciclovir crema', 'Dermatológico', 'cat-derm', '5%', 'Antiviral tópico. Trata el herpes labial y herpes simple cutáneo.', 'Aplicar 5 veces al día por 4–5 días.', 'Herpes labial (fuego), herpes cutáneo.', 'Apenas sientas ese hormigueo del herpes labial, aplica el aciclovir. Cuanto antes lo uses, mejor resultado.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ketoconazol crema', 'Dermatológico', 'cat-derm', '2%', 'Antifúngico tópico potente. Trata tiña, caspa y sebodermitis.', 'Aplicar una vez al día por 2–4 semanas.', 'Tiña, dermatitis seborreica, candidiasis cutánea.', 'El ketoconazol ataca los hongos con fuerza. Para la caspa también lo hay en champú — muy efectivo.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Peróxido de benzoilo', 'Dermatológico', 'cat-derm', '5%', 'Antibacteriano y queratolítico. Trata el acné inflamatorio.', 'Aplicar capa fina en zonas afectadas una vez al día.', 'Acné moderado, espinillas inflamadas.', 'El peróxido de benzoilo es muy efectivo para el acné pero puede secar la piel. Empieza despacio y usa hidratante.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Betametasona crema', 'Dermatológico', 'cat-derm', '0.05%', 'Corticoide tópico potente. Trata dermatitis, eccema y psoriasis.', 'Aplicar capa fina 1–2 veces al día.', 'Eccema severo, dermatitis, psoriasis en placa.', 'La betametasona es muy potente para la inflamación de piel. Poquito, pocos días y nunca en la cara sin receta.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Mupirocina ungüento', 'Dermatológico', 'cat-derm', '2%', 'Antibiótico tópico. Trata infecciones bacterianas de la piel como impétigo.', 'Aplicar 3 veces al día por 5–10 días.', 'Impétigo, heridas infectadas, foliculitis.', 'La mupirocina es el antibiótico de la piel. Para esas heridas que no cicatrizan bien o se infectan.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Tretinoína crema', 'Dermatológico', 'cat-derm', '0.025%', 'Retinoide tópico. Trata el acné y signos de envejecimiento cutáneo.', 'Aplicar una vez al día en la noche, en piel limpia y seca.', 'Acné, manchas, antienvejecimiento — solo con indicación.', 'La tretinoína es muy poderosa para el acné y las manchas. Pero exige paciencia — los primeros días puede irritar.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Colchicina', 'Analgésico', 'cat-analg', '0.5 mg', 'Antiinflamatorio específico para gota y pericarditis.', '0.5–1.2 mg al inicio del ataque de gota, luego 0.5 mg cada 8 horas.', 'Solo con prescripción. Crisis de gota, pericarditis.', 'La colchicina es el tratamiento estrella para los ataques de gota. Funciona muy bien si se toma pronto.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Pregabalina', 'Analgésico', 'cat-analg', '75 mg', 'Anticonvulsivante y analgésico neuropático. Trata el dolor nervioso.', '75–300 mg al día dividido en 2–3 tomas.', 'Solo con prescripción. Neuralgia, fibromialgia, neuropatía diabética.', 'La pregabalina trata ese dolor quemante o eléctrico de los nervios. Es efectiva pero requiere ajuste gradual de dosis.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Alprazolam', 'Analgésico', 'cat-analg', '0.5 mg', 'Benzodiazepina de acción rápida. Trata ansiedad y ataques de pánico.', '0.25–0.5 mg 2–3 veces al día.', 'SOLO CON PRESCRIPCIÓN MÉDICA para ansiedad.', 'El alprazolam calma la ansiedad rápido, pero crea dependencia. Solo bajo estricto control médico y por el menor tiempo posible.', '🧠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Sertralina', 'Analgésico', 'cat-analg', '50 mg', 'Antidepresivo ISRS. Trata depresión, ansiedad y trastorno obsesivo-compulsivo.', '50–200 mg una vez al día.', 'Solo con prescripción. Depresión, trastorno de ansiedad, TOC.', 'La sertralina es uno de los antidepresivos más seguros. Tiene que pasar un tiempo para que haga efecto — la constancia es clave.', '🧠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Fluoxetina', 'Analgésico', 'cat-analg', '20 mg', 'Antidepresivo ISRS. Trata depresión, bulimia y trastorno de pánico.', '20 mg una vez al día por la mañana.', 'Solo con prescripción. Depresión, TOC, trastornos de conducta alimentaria.', 'La fluoxetina es un clásico entre los antidepresivos. Tómala por la mañana para evitar que interfiera con el sueño.', '🧠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Lágrimas artificiales', 'Dermatológico', 'cat-derm', 'Colirio', 'Lubricantes oculares. Alivian la sequedad y el picor ocular.', '1–2 gotas en cada ojo según necesidad.', 'Ojo seco, irritación, fatiga visual por pantallas.', 'Las lágrimas artificiales son el remedio perfecto para los ojos cansados de pantallas. Completamente seguras y muy aliviadoras.', '👁️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Tobramicina colirio', 'Antibiótico', 'cat-antib', '0.3%', 'Antibiótico oftálmico. Trata conjuntivitis bacteriana.', '1–2 gotas cada 4 horas en el ojo afectado.', 'Solo con prescripción. Conjuntivitis bacteriana, blefaritis.', 'Cuando el ojo está infectado y secreta pus, el tobramicina colirio lo ataca directamente. Higiene al aplicarlo.', '👁️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Tamsulosina', 'Cardiovascular', 'cat-card', '0.4 mg', 'Alfa-bloqueador. Alivia síntomas urinarios por hiperplasia prostática benigna.', '0.4 mg una vez al día después de las comidas.', 'Solo con prescripción. Hiperplasia prostática, dificultad urinaria.', 'La tamsulosina relaja los músculos de la próstata y mejora el flujo urinario. Muy usada en hombres mayores.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Fenazopiridina', 'Analgésico', 'cat-analg', '200 mg', 'Analgésico urinario. Alivia el ardor y el dolor al orinar.', '200 mg tres veces al día después de las comidas.', 'Ardor urinario, cistitis, después de procedimientos urológicos.', 'La fenazopiridina calma ese ardor horrible al orinar. Ojo: la orina se vuelve naranja — no te asustes, es normal.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Albendazol', 'Antibiótico', 'cat-antib', '400 mg', 'Antiparasitario de amplio espectro. Trata infecciones por helmintos.', '400 mg dosis única o según indicación.', 'Solo con indicación médica. Parasitosis intestinal, giardia.', 'El albendazol elimina varios tipos de parásitos intestinales con una sola dosis. Ideal para tratamientos en zonas tropicales.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Mebendazol', 'Antibiótico', 'cat-antib', '100 mg', 'Antiparasitario. Trata infecciones por oxiuros, áscaris y uncinarias.', '100 mg dos veces al día por 3 días.', 'Solo con indicación médica. Oxiuros, áscaris, anquilostomas.', 'Los parásitos intestinales son más comunes de lo que se cree. El mebendazol los elimina de forma efectiva y segura.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Fluconazol', 'Antibiótico', 'cat-antib', '150 mg', 'Antifúngico sistémico. Trata candidiasis oral, vaginal y cutánea.', '150 mg dosis única para candidiasis vaginal.', 'Solo con prescripción. Candidiasis vaginal, oral (muguet).', 'El fluconazol resuelve la candidiasis con una sola pastilla. Pero siempre con diagnóstico confirmado.', '🟣');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Terbinafina crema', 'Dermatológico', 'cat-derm', '1%', 'Antifúngico tópico altamente eficaz contra dermatofitos.', 'Aplicar una vez al día por 1–2 semanas.', 'Pie de atleta, tiña corporal, onicomicosis superficial.', 'La terbinafina mata los hongos de la piel con más eficacia que otros antifúngicos. Completa el tratamiento para evitar recaídas.', '🔴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Alcohol antiséptico 70°', 'Dermatológico', 'cat-derm', '70%', 'Antiséptico cutáneo. Desinfecta la piel y superficies.', 'Aplicar en la zona a desinfectar con algodón o gasa.', 'Desinfección de heridas leves, preparación de piel antes de inyecciones.', 'El alcohol al 70% es el desinfectante básico de cualquier botiquín. A esa concentración mata bacterias eficientemente.', '🧴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Agua oxigenada (H₂O₂)', 'Dermatológico', 'cat-derm', '3%', 'Antiséptico y limpiador de heridas. Oxigena las lesiones y previene infecciones.', 'Aplicar directamente en la herida con gasa.', 'Heridas superficiales, cortes, raspaduras.', 'El agua oxigenada limpia la herida y hace esa efervescencia que indica que está actuando. Solo para heridas pequeñas.', '🩹');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Povidona yodada', 'Dermatológico', 'cat-derm', '10%', 'Antiséptico potente de amplio espectro. Para desinfección de heridas y piel.', 'Aplicar en la zona afectada sin diluir o diluida al 1% para mucosas.', 'Heridas, quemaduras leves, preparación quirúrgica.', 'La povidona yodada es un antiséptico muy potente. Ideal para heridas con riesgo de infección.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Dimenhidrinato', 'Gastroprotector', 'cat-gast', '50 mg', 'Antihistamínico antiemético. Previene y trata el mareo por movimiento.', '50 mg 30 minutos antes del viaje. Cada 4–6 horas si es necesario.', 'Mareo por viaje (auto, barco, avión), vértigo.', '¿Te mareas en el carro? El dimenhidrinato es tu aliado. Tómalo antes de salir para que haga efecto a tiempo.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Escopolamina', 'Gastroprotector', 'cat-gast', '0.33 mg', 'Anticolinérgico. Previene el mareo por movimiento y reduce cólicos.', '1 parche retroauricular 4 horas antes del viaje, o tabletas según indicación.', 'Mareo por viaje prolongado, náuseas postoperatorias.', 'El parche de escopolamina es genial para viajes largos en barco o avión. Se pone detrás de la oreja y ya.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Betahistina', 'Cardiovascular', 'cat-card', '16 mg', 'Reduce la presión en el oído interno. Trata el vértigo y la enfermedad de Ménière.', '16 mg dos o tres veces al día con las comidas.', 'Solo con prescripción. Vértigo, enfermedad de Ménière.', 'La betahistina es el tratamiento de elección para el vértigo crónico. Mejora la circulación en el oído interno.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Nistatina suspensión', 'Antibiótico', 'cat-antib', '100.000 UI/ml', 'Antifúngico para candidiasis oral (muguet) especialmente en bebés.', '1 ml en cada lado de la boca 4 veces al día.', 'Muguet oral en bebés y adultos inmunosuprimidos.', 'La nistatina es el tratamiento estándar para el muguet. Muy segura incluso en bebés pequeños.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('N-acetilcisteína', 'Respiratorio', 'cat-resp', '600 mg', 'Mucolítico y antioxidante. Fluidifica el moco y protege el hígado en intoxicaciones.', '600 mg una vez al día o en sobre efervescente.', 'Tos con flema densa, EPOC, bronquitis crónica.', 'La N-acetilcisteína es un mucolítico poderoso que también cuida el hígado. El olor a huevo es normal — no te preocupes.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Carbón activado', 'Gastroprotector', 'cat-gast', '500 mg', 'Adsorbente intestinal. Captura toxinas y gases en el tubo digestivo.', '25–50 g disuelto en agua en caso de intoxicación (urgente).', 'Intoxicaciones leves, flatulencia excesiva.', 'El carbón activado atrapa las toxinas antes de que el cuerpo las absorba. En intoxicaciones siempre llama a emergencias primero.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Hidroxizina', 'Antihistamínico', 'cat-antih', '25 mg', 'Antihistamínico ansiolítico. Trata ansiedad y picazón intensa.', '25 mg 3–4 veces al día o 50 mg para insomnio.', 'Solo con prescripción. Ansiedad, urticaria severa, insomnio.', 'La hidroxizina calma tanto el picor como la ansiedad. Es de las más seguras para el manejo de ansiedad puntual.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Probióticos (Lactobacillus)', 'Gastroprotector', 'cat-gast', '2.000 Mill UFC', 'Restauran la flora intestinal. Útiles durante y después del tratamiento con antibióticos.', '1 cápsula al día con o sin alimentos.', 'Durante tratamiento antibiótico, diarrea, desequilibrio intestinal.', 'Los probióticos son el ejército bueno del intestino. Cuando los antibióticos desequilibran la flora, estos la restauran.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Jengibre (extracto)', 'Gastroprotector', 'cat-gast', '500 mg', 'Antiemético natural. Alivia las náuseas del embarazo, viajes y quimioterapia.', '500 mg 1–4 veces al día.', 'Náuseas leves, mareo por viaje, náuseas del embarazo.', 'El jengibre es uno de los antinaúseas naturales más eficaces. Muy seguro durante el embarazo para las náuseas matutinas.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Alopurinol', 'Analgésico', 'cat-analg', '100 mg', 'Reduce los niveles de ácido úrico en sangre. Previene ataques de gota.', '100–300 mg al día con abundante agua.', 'Solo con prescripción. Gota crónica, hiperuricemia, cálculos de urato.', 'El alopurinol previene la gota bajando el ácido úrico. No se toma en el ataque sino entre ataques, como prevención.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Beclometasona nasal', 'Respiratorio', 'cat-resp', '50 mcg', 'Corticoide nasal. Reduce la inflamación y congestión en rinitis alérgica crónica.', '1–2 pulsaciones en cada fosa nasal una o dos veces al día.', 'Rinitis alérgica crónica, poliposis nasal, bajo prescripción.', 'La beclometasona nasal no actúa al instante pero su efecto es muy duradero y eficaz. La constancia es la clave.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Gabapentina', 'Analgésico', 'cat-analg', '300 mg', 'Anticonvulsivante y analgésico neuropático. Reduce el dolor de nervios dañados.', '300 mg al inicio, aumentar gradualmente hasta 900–1800 mg/día en 3 tomas.', 'Solo con prescripción. Neuropatía, neuralgia posherpética, epilepsia.', 'La gabapentina calma el dolor neuropático — ese ardor o descarga eléctrica que viene de los nervios. Requiere paciencia y ajuste gradual.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Biotina (Vitamina B7)', 'Vitamina', 'cat-vita', '5 mg', 'Vitamina esencial para la salud del cabello, uñas y metabolismo energético.', '5 mg al día con el desayuno.', 'Caída del cabello, uñas frágiles, deficiencia de biotina.', 'La biotina apoya el cabello y las uñas. Si vas a hacerte analíticas, avisa al médico que la tomas — puede alterar algunos resultados.', '💛');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Celecoxib', 'Analgésico', 'cat-analg', '200 mg', 'Antiinflamatorio inhibidor selectivo de COX-2. Menor riesgo gástrico que el ibuprofeno.', '200 mg una o dos veces al día con alimentos.', 'Solo con prescripción. Artrosis, artritis reumatoide, dolor crónico.', 'El celecoxib es un antiinflamatorio más amigable con el estómago. Ideal para quienes tienen gastritis pero necesitan controlar la inflamación crónica.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Metamisol (Dipirona)', 'Analgésico', 'cat-analg', '500 mg', 'Analgésico y antipirético potente. Muy eficaz para cólicos y dolor visceral.', '500–1000 mg cada 8 horas. Máximo 3 g/día.', 'Dolor cólico (renal, biliar), fiebre resistente, dolor postoperatorio.', 'La dipirona es excelente para el cólico renal o biliar — ese dolor que te dobla. Pero siempre es importante saber la causa del dolor primero.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Clindamicina', 'Antibiótico', 'cat-antib', '300 mg', 'Antibiótico lincosamida. Activo contra bacterias anaerobias y gram-positivas.', '300–450 mg cada 6–8 horas con alimentos.', 'Solo con prescripción. Infecciones dentales, piel, pelvis, abscesos.', 'La clindamicina es muy eficaz para infecciones dentales y de partes blandas. Si tienes diarrea muy intensa durante el tratamiento, avisa al médico.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Nitrofurantoína', 'Antibiótico', 'cat-antib', '100 mg', 'Antibiótico urinario. Solo actúa en el tracto urinario, ideal para cistitis sin complicaciones.', '100 mg cada 12 horas por 5–7 días con alimentos.', 'Solo con prescripción. Infección urinaria baja (cistitis).', 'La nitrofurantoína ataca la infección directamente en la vejiga. La orina oscura es normal — no te asustes.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Cefadroxilo', 'Antibiótico', 'cat-antib', '500 mg', 'Cefalosporina de primera generación. Trata infecciones de piel, amígdalas y urinarias.', '500 mg cada 12 horas por 7–10 días.', 'Solo con prescripción. Amigdalitis estreptocócica, impétigo, cistitis.', 'El cefadroxilo es un antibiótico de primera línea muy fiable para infecciones de garganta y piel. Completa los días indicados aunque te sientas mejor.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Bisoprolol', 'Cardiovascular', 'cat-card', '5 mg', 'Betabloqueante cardioselectivo. Reduce la frecuencia cardíaca y la presión arterial.', '5–10 mg una vez al día por la mañana.', 'Solo con prescripción. Hipertensión, insuficiencia cardíaca, arritmias.', 'El bisoprolol desacelera el corazón y lo protege. Nunca se suspende de golpe — siempre hay que ir bajando la dosis gradualmente.', '❤️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Warfarina', 'Cardiovascular', 'cat-card', '5 mg', 'Anticoagulante oral. Previene y trata trombosis y embolias.', 'Dosis individualizada según INR (generalmente 2–10 mg/día).', 'Solo con prescripción. Fibrilación auricular, trombosis venosa, válvulas protésicas.', 'La warfarina adelgaza la sangre para evitar coágulos peligrosos. Requiere controles frecuentes — la dosis se ajusta según resultados.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Tiotropio', 'Respiratorio', 'cat-resp', '18 mcg', 'Broncodilatador anticolinérgico de larga duración. Para EPOC y asma grave.', '1 inhalación al día con el dispositivo HandiHaler.', 'Solo con prescripción. EPOC, asma no controlada.', 'El tiotropio abre los bronquios durante 24 horas con solo una inhalación diaria. Es el tratamiento de mantenimiento en el EPOC.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Fluticasona inhalada', 'Respiratorio', 'cat-resp', '250 mcg', 'Corticoide inhalado. Reduce la inflamación crónica de las vías aéreas en asma y EPOC.', '1–2 pulsaciones dos veces al día.', 'Solo con prescripción. Asma moderada a grave, EPOC con exacerbaciones frecuentes.', 'La fluticasona inhalada apaga la inflamación bronquial de fondo. Enjuaga la boca siempre después de usarla para evitar hongos.', '🫁');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Guaifenesina', 'Respiratorio', 'cat-resp', '400 mg', 'Expectorante. Fluidifica las secreciones bronquiales para facilitar su expulsión.', '400 mg cada 4 horas con abundante agua.', 'Tos productiva con moco espeso, bronquitis, resfriado con congestión.', 'La guaifenesina hace que el moco sea más fluido para que puedas expulsarlo mejor. Bebe mucha agua — el agua es su mejor aliado.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Lansoprazol', 'Gastroprotector', 'cat-gast', '30 mg', 'Inhibidor de bomba de protones. Reduce la acidez gástrica de forma potente.', '30 mg una vez al día antes del desayuno.', 'Úlcera gástrica, esofagitis por reflujo, erradicación de H. pylori.', 'El lansoprazol bloquea la producción de ácido con mucha eficacia. Para que funcione bien, tómalo 30 minutos antes de desayunar.', '🟢');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Bismuto subsalicilato', 'Gastroprotector', 'cat-gast', '524 mg', 'Protege la mucosa gástrica. Alivia indigestión, diarrea y náuseas.', '524 mg (30 ml) cada 30–60 minutos según necesidad. Máximo 8 dosis/día.', 'Diarrea del viajero, indigestión, náuseas, ardor estomacal.', 'El bismuto crea una capa protectora sobre la mucosa. La lengua y las heces negras son normales — no te asustes.', '🟤');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Simeticona', 'Gastroprotector', 'cat-gast', '80 mg', 'Antiespumante intestinal. Elimina los gases acumulados en el estómago e intestino.', '80–125 mg después de cada comida y al acostarse.', 'Gases, hinchazón, cólico del lactante.', 'La simeticona rompe las burbujas de gas en el intestino y las elimina. Muy segura para bebés con cólicos.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Levotiroxina', 'Vitamina', 'cat-vita', '50 mcg', 'Hormona tiroidea sintética. Trata el hipotiroidismo reemplazando la hormona que falta.', '25–100 mcg en ayunas 30 minutos antes del desayuno.', 'Solo con prescripción. Hipotiroidismo, bocio, cáncer de tiroides postoperatorio.', 'La levotiroxina reemplaza la hormona que la tiroides no produce. La hora y el ayuno son clave para que se absorba bien.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Zinc óxido pasta', 'Dermatológico', 'cat-derm', '20%', 'Protector y cicatrizante cutáneo. Ideal para dermatitis del pañal y heridas superficiales.', 'Aplicar una capa generosa en la zona a proteger.', 'Dermatitis del pañal, rozaduras, eccemas húmedos.', 'La pasta de óxido de zinc crea una barrera protectora perfecta para el culito del bebé. Es el tratamiento clásico de la dermatitis del pañal.', '🧴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Permetrina crema', 'Dermatológico', 'cat-derm', '5%', 'Antiparasitario tópico. Elimina la sarna y los piojos del cuero cabelludo.', 'Aplicar en todo el cuerpo (sarna) o en el cabello (piojos) y lavar tras el tiempo indicado.', 'Solo con indicación médica. Escabiosis (sarna), pediculosis.', 'La permetrina elimina la sarna y los piojos de forma muy eficaz. Toda la familia debe tratarse a la vez para evitar reinfecciones.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Vitamina A', 'Vitamina', 'cat-vita', '5000 UI', 'Esencial para la visión, el sistema inmunológico y la piel.', '5000 UI al día con alimentos que contengan grasa.', 'Deficiencia de vitamina A, visión nocturna reducida, piel seca.', 'La vitamina A cuida los ojos y la piel. A diferencia de las vitaminas del grupo B, se acumula en el cuerpo — no hay que pasarse con la dosis.', '🟠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Vitamina B12 (Cianocobalamina)', 'Vitamina', 'cat-vita', '1000 mcg', 'Esencial para la función neurológica, formación de glóbulos rojos y el metabolismo.', '1000 mcg al día vía oral o intramuscular.', 'Anemia megaloblástica, deficiencia en veganos, neuropatía por déficit.', 'La B12 es la vitamina que los veganos y adultos mayores suelen necesitar suplementar. Es fundamental para los nervios y la sangre.', '🔵');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Vitamina K2', 'Vitamina', 'cat-vita', '100 mcg', 'Dirige el calcio a los huesos y arterias. Complementa a la vitamina D3.', '100 mcg al día con alimentos grasos.', 'Osteoporosis, calcificación arterial, suplementación junto a vitamina D.', 'La vitamina K2 lleva el calcio adonde debe ir: a los huesos, no a las arterias. Siempre combínala con vitamina D3 para mejores resultados.', '🦴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Magnesio glicinato', 'Vitamina', 'cat-vita', '400 mg', 'Suplemento de magnesio. Alivia calambres, mejora el sueño y reduce la ansiedad leve.', '400 mg al día por la noche.', 'Calambres musculares, insomnio leve, déficit de magnesio.', 'El magnesio glicinato relaja los músculos y mejora el sueño. Tómalo de noche — notarás la diferencia en la calidad del descanso.', '🧪');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Timolol colirio', 'Cardiovascular', 'cat-card', '0.5%', 'Betabloqueante oftálmico. Reduce la presión intraocular en el glaucoma.', '1 gota en el ojo afectado dos veces al día.', 'Solo con prescripción. Glaucoma de ángulo abierto, hipertensión ocular.', 'El timolol baja la presión del ojo para proteger el nervio óptico. Aunque es un colirio, se absorbe algo al torrente sanguíneo — avisa si tienes asma.', '👁️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ciprofloxacino colirio', 'Antibiótico', 'cat-antib', '0.3%', 'Antibiótico fluoroquinolona oftálmico. Trata infecciones oculares bacterianas graves.', '1–2 gotas en el ojo afectado cada 2–4 horas los primeros días.', 'Solo con prescripción. Conjuntivitis bacteriana grave, úlcera corneal.', 'El ciprofloxacino oftálmico es el antibiótico más potente para infecciones serias del ojo. Solo con receta y siempre con higiene.', '👁️');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Clonazepam', 'Analgésico', 'cat-analg', '0.5 mg', 'Benzodiacepina anticonvulsivante. Trata epilepsia, ansiedad y trastorno de pánico.', '0.5–2 mg dos o tres veces al día.', 'Solo con prescripción. Epilepsia, trastorno de pánico, ansiedad severa.', 'El clonazepam es más duradero que el alprazolam. Se usa para la epilepsia y la ansiedad severa siempre con seguimiento médico estrecho.', '🧠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Quetiapina', 'Analgésico', 'cat-analg', '25 mg', 'Antipsicótico atípico. Trata esquizofrenia, bipolaridad e insomnio en dosis bajas.', '25–50 mg para insomnio; 150–800 mg para psicosis.', 'Solo con prescripción. Esquizofrenia, trastorno bipolar, insomnio crónico.', 'La quetiapina en dosis bajas se usa para el insomnio refractario. En dosis altas, controla la psicosis. Siempre bajo supervisión estricta.', '🧠');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Valeriana (extracto)', 'Vitamina', 'cat-vita', '450 mg', 'Sedante suave natural. Ayuda a conciliar el sueño y reduce la ansiedad leve.', '300–600 mg 30–60 minutos antes de dormir.', 'Insomnio leve, ansiedad puntual, estrés.', 'La valeriana es el somnífero natural más estudiado. No actúa en la primera noche — hay que darle unas semanas para que funcione.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Pasiflora (extracto)', 'Vitamina', 'cat-vita', '250 mg', 'Ansiolítico natural suave. Reduce la ansiedad y mejora la calidad del sueño.', '250 mg 2–3 veces al día o 500 mg antes de dormir.', 'Ansiedad leve, insomnio por nerviosismo, estrés.', 'La pasiflora calma la ansiedad suavemente. Muchas personas la prefieren porque no genera dependencia como las benzodiacepinas.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Dexpantenol crema', 'Dermatológico', 'cat-derm', '5%', 'Provitamina B5. Hidrata, regenera y cicatriza la piel dañada o irritada.', 'Aplicar en la zona afectada 2–3 veces al día.', 'Quemaduras leves, dermatitis del pañal, heridas superficiales, piel seca.', 'El dexpantenol es la crema cicatrizante por excelencia. Hidrata la piel dañada y acelera su reparación. Muy seguro para toda la familia.', '🧴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Clorfenamina', 'Antihistamínico', 'cat-antih', '4 mg', 'Antihistamínico de primera generación. Alivia la alergia y el resfriado. Causa sedación.', '4 mg cada 6–8 horas.', 'Alergia, urticaria, resfriado con rinorrea, picaduras.', 'La clorfenamina es el antihistamínico clásico que te da sueño. Ideal para tomarlo de noche o cuando no necesitas conducir.', '💊');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Ácido hialurónico oral', 'Vitamina', 'cat-vita', '120 mg', 'Apoya la hidratación de articulaciones y piel. Complemento en osteoartritis.', '120 mg una vez al día.', 'Dolor articular leve, piel seca, osteoartritis incipiente.', 'El ácido hialurónico oral lubrica las articulaciones y la piel desde adentro. Los resultados son graduales — dale tiempo.', '🌿');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Condroitín + Glucosamina', 'Vitamina', 'cat-vita', '400/500 mg', 'Suplemento para el cartílago articular. Reduce el dolor y enlentece el deterioro en osteoartritis.', '1 comprimido dos veces al día con las comidas.', 'Osteoartritis, dolor articular crónico de rodillas, cadera.', 'El condroitín y la glucosamina alimentan el cartílago de las articulaciones. La clave es la constancia — en semanas notarás la diferencia.', '🦴');
insert into medicine (name, category, category_class, dose, uses, posology, when_to_take, mol_tip, emoji) values ('Piridoxina (Vitamina B6)', 'Vitamina', 'cat-vita', '50 mg', 'Vitamina B6. Alivia las náuseas del embarazo y apoya el sistema nervioso.', '10–50 mg al día según indicación.', 'Náuseas del embarazo (con doxilamina), deficiencia de B6, síndrome premenstrual.', 'La vitamina B6 es el tratamiento de primera línea para las náuseas del embarazo. En dosis normales es completamente segura para madre y bebé.', '💊');
